```html
<section class="pys-section-root pys-tirzepatida-mx" id="tirzepatida-en-mexico">
  <style>
    .pys-tirzepatida-mx{
      --pys-bg:#090a0b;
      --pys-dark:#111214;
      --pys-panel:#151719;
      --pys-panel2:#1a1117;
      --pys-text:#f5f5f2;
      --pys-muted:#cfd5d2;
      --pys-soft:#aeb8b4;
      --pys-cyan:#00e5c4;
