      overflow:hidden;
      padding:0;
      font-family:"Inter","Helvetica Neue",Arial,sans-serif;
      color:var(--pys-text);
      background:
        radial-gradient(circle at 10% 14%,rgba(0,229,196,.17),transparent 28%),
        radial-gradient(circle at 88% 10%,rgba(247,0,122,.16),transparent 26%),
        radial-gradient(circle at 50% 60%,rgba(0,229,196,.06),transparent 34%),
        linear-gradient(135deg,#090a0b 0%,#111214 48%,#1a1117 100%);
      isolation:isolate;
    }

    .pys-tirzepatida-mx *{box-sizing:border-box}
    .pys-tirzepatida-mx a{text-decoration:none!important}

    .pys-tz-wrap{
      width:min(100% - 32px,1180px);
      margin:auto;
      position:relative;
      z-index:3;
    }

    .pys-tz-grid-bg{
      position:absolute;
      inset:0;
      opacity:.25;
      pointer-events:none;
      background-image:
        linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),
        linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);
      background-size:38px 38px;
      mask-image:linear-gradient(to bottom,rgba(0,0,0,.95),transparent 80%);
      z-index:0;
    }

    .pys-tz-glow{
      position:absolute;
      border-radius:999px;
      pointer-events:none;
      z-index:1;
      opacity:.5;
      filter:blur(5px);
      animation:pysGlowMove 9s ease-in-out infinite alternate;
    }

    .pys-tz-glow-a{
      width:260px;
      height:260px;
      top:250px;
      left:-110px;
      background:radial-gradient(circle,rgba(0,229,196,.23),transparent 68%);
    }

    .pys-tz-glow-b{
      width:320px;
      height:320px;
      top:620px;
      right:-130px;
      background:radial-gradient(circle,rgba(247,0,122,.22),transparent 70%);
      animation-delay:1.4s;
    }

    .pys-tz-glow-c{
      width:240px;
      height:240px;
      bottom:360px;
      left:32%;
      background:radial-gradient(circle,rgba(0,229,196,.13),transparent 70%);
      animation-delay:2.2s;
    }

    @keyframes pysGlowMove{
      from{transform:translate3d(0,0,0) scale(1)}
      to{transform:translate3d(28px,-34px,0) scale(1.08)}
    }

    .pys-tz-hero{
      position:relative;
      padding:110px 0 86px;
    }

    .pys-tz-hero-grid{
      display:grid;
      grid-template-columns:1.04fr .96fr;
      gap:56px;
      align-items:center;
    }

    .pys-tz-badge,
    .pys-tz-tag{
      display:inline-flex;
      align-items:center;
      gap:10px;
      border-radius:999px;
      text-transform:uppercase;
      font-weight:950;
      letter-spacing:.12em;
    }

    .pys-tz-badge{
      padding:12px 18px;
      margin-bottom:28px;
      color:#fff;
      font-size:.75rem;
      border:1px solid rgba(255,255,255,.12);
      background:rgba(255,255,255,.06);
      backdrop-filter:blur(14px);
      box-shadow:0 18px 44px rgba(0,0,0,.18);
    }

    .pys-tz-badge:before,
    .pys-tz-tag:before{
      content:"";
      width:9px;
      height:9px;
      border-radius:50%;
      background:linear-gradient(135deg,var(--pys-cyan),var(--pys-pink));
      box-shadow:0 0 16px rgba(0,229,196,.7);
    }

    .pys-tz-title{
      margin:0;
      max-width:820px;
      font-family:"Optima","Optima LT Std","Candara","Segoe UI",Arial,sans-serif;
      font-size:clamp(3.1rem,6.8vw,6.8rem);
      line-height:.9;
      font-weight:400;
      letter-spacing:-.065em;
      color:#fff;
    }

    .pys-tz-title span{
      background:linear-gradient(135deg,var(--pys-cyan),#fff 45%,var(--pys-pink));
      -webkit-background-clip:text;
      background-clip:text;
      -webkit-text-fill-color:transparent;
    }

    .pys-tz-copy{
      margin:30px 0 0;
      max-width:720px;
      color:var(--pys-muted);
      line-height:1.9;
      font-size:1.04rem;
    }

    .pys-tz-copy strong{color:#fff}

    .pys-tz-actions{
      display:flex;
      flex-wrap:wrap;
      gap:14px;
      margin-top:34px;
    }

    .pys-tz-btn{
      min-height:56px;
      padding:16px 28px;
      border-radius:999px;
      display:inline-flex;
      align-items:center;
      justify-content:center;
      gap:10px;
      text-transform:uppercase;
      letter-spacing:.105em;
      font-size:.73rem;
      font-weight:950;
      transition:.28s ease;
      cursor:pointer;
      border:0;
      white-space:nowrap;
    }

    .pys-tz-btn svg{
      width:18px;
      height:18px;
      flex:0 0 18px;
    }

    .pys-tz-btn-primary{
      background:var(--pys-cyan);
      color:#111!important;
      box-shadow:0 18px 44px rgba(0,229,196,.25);
    }

    .pys-tz-btn-secondary{
      color:#fff!important;
      border:1px solid rgba(255,255,255,.15);
      background:rgba(255,255,255,.06);
      backdrop-filter:blur(14px);
    }

    .pys-tz-btn-wa{
      background:var(--pys-wa);
      color:#06130b!important;
      box-shadow:0 18px 44px rgba(37,211,102,.18);
    }

    .pys-tz-btn:hover{
      transform:translateY(-4px);
      filter:saturate(1.08);
    }

    .pys-tz-keypoints{
      display:flex;
      flex-wrap:wrap;
      gap:12px;
      margin-top:26px;
    }

    .pys-tz-keypoint{
      display:inline-flex;
      align-items:center;
      gap:9px;
      padding:10px 13px;
      border-radius:999px;
      background:rgba(255,255,255,.055);
      border:1px solid rgba(255,255,255,.1);
      color:#dce2df;
      font-size:.78rem;
      line-height:1;
    }

    .pys-tz-keypoint i{
      width:8px;
      height:8px;
      border-radius:999px;
      background:var(--pys-cyan);
      box-shadow:0 0 16px rgba(0,229,196,.75);
    }

    .pys-tz-visual{
      position:relative;
      min-height:690px;
      border-radius:38px;
      overflow:hidden;
      background:
        radial-gradient(circle at top left,rgba(0,229,196,.18),transparent 32%),
        radial-gradient(circle at bottom right,rgba(247,0,122,.20),transparent 30%),
        linear-gradient(145deg,#111315,#1b1d20);
      border:1px solid rgba(255,255,255,.11);
      box-shadow:0 34px 80px rgba(0,0,0,.38);
    }

    .pys-tz-visual:before{
      content:"";
      position:absolute;
      inset:18px;
      border-radius:28px;
      border:1px solid rgba(255,255,255,.08);
      background:
        linear-gradient(rgba(255,255,255,.03) 1px,transparent 1px),
        linear-gradient(90deg,rgba(255,255,255,.03) 1px,transparent 1px);
      background-size:34px 34px;
      z-index:1;
    }

    .pys-tz-watermark{
      position:absolute;
      top:34px;
      right:34px;
      font-size:5.6rem;
      line-height:.9;
      font-family:"Optima","Optima LT Std","Candara","Segoe UI",Arial,sans-serif;
      color:rgba(255,255,255,.055);
      letter-spacing:-.08em;
      z-index:2;
    }

    .pys-tz-hero-img{
      position:absolute;
      inset:auto 50% 0 auto;
      transform:translateX(50%);
      width:100%;
      max-width:760px;
      z-index:3;
      object-fit:contain;
      filter:drop-shadow(0 34px 56px rgba(0,0,0,.48));
      animation:pysHeroFloat 5.6s ease-in-out infinite;
    }

    @keyframes pysHeroFloat{
      0%,100%{transform:translateX(50%) translateY(0)}
      50%{transform:translateX(50%) translateY(-14px)}
    }

    .pys-tz-floating{
      position:absolute;
      top:28px;
      left:28px;
      width:280px;
      border-radius:26px;
      padding:22px;
      background:rgba(255,255,255,.08);
      border:1px solid rgba(255,255,255,.12);
      backdrop-filter:blur(16px);
      z-index:5;
      box-shadow:0 18px 44px rgba(0,0,0,.25);
    }

    .pys-tz-floating h3{
      margin:0 0 12px;
      color:var(--pys-cyan);
      font-size:.86rem;
      letter-spacing:.12em;
      text-transform:uppercase;
    }

    .pys-tz-floating p{
      margin:0;
      color:#d9dcd9;
      line-height:1.65;
      font-size:.92rem;
    }

    .pys-tz-pill{
      position:absolute;
      right:24px;
      bottom:24px;
      display:inline-flex;
      align-items:center;
      gap:9px;
      padding:14px 18px;
      border-radius:999px;
      background:var(--pys-pink);
      color:#fff;
      text-transform:uppercase;
      letter-spacing:.12em;
      font-size:.7rem;
      font-weight:950;
      z-index:5;
      box-shadow:0 16px 40px rgba(247,0,122,.25);
    }

    .pys-tz-pill:before{
      content:"";
      width:8px;
      height:8px;
      border-radius:50%;
      background:#fff;
      box-shadow:0 0 14px rgba(255,255,255,.85);
    }

    .pys-tz-section{
      position:relative;
      padding:88px 0;
      z-index:2;
    }

    .pys-tz-section-soft{
      background:linear-gradient(180deg,rgba(255,255,255,.025),rgba(255,255,255,0));
    }

    .pys-tz-head{
      max-width:880px;
      margin-bottom:48px;
    }

    .pys-tz-tag{
      color:var(--pys-cyan);
      font-size:.74rem;
      margin-bottom:18px;
    }

    .pys-tz-section-title{
      margin:0;
      max-width:950px;
      font-family:"Optima","Optima LT Std","Candara","Segoe UI",Arial,sans-serif;
      font-size:clamp(2.05rem,4vw,4.15rem);
      line-height:1;
      font-weight:400;
      letter-spacing:-.055em;
      color:#fff;
    }

    .pys-tz-section-title span{
      background:linear-gradient(135deg,var(--pys-cyan),var(--pys-pink));
      -webkit-background-clip:text;
      background-clip:text;
      -webkit-text-fill-color:transparent;
    }

    .pys-tz-section-copy{
      margin:24px 0 0;
      color:var(--pys-muted);
      line-height:1.9;
      font-size:1.02rem;
    }

    .pys-tz-two{
      display:grid;
      grid-template-columns:1fr 1fr;
      gap:24px;
    }

    .pys-tz-grid-3{
      display:grid;
      grid-template-columns:repeat(3,1fr);
      gap:24px;
    }

    .pys-tz-grid-4{
      display:grid;
      grid-template-columns:repeat(4,1fr);
      gap:18px;
    }

    .pys-tz-card,
    .pys-tz-info-card{
      position:relative;
      border-radius:30px;
      padding:34px;
      background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.035));
      border:1px solid rgba(255,255,255,.12);
      box-shadow:0 22px 48px rgba(0,0,0,.24);
      overflow:hidden;
      transition:.28s ease;
    }

    .pys-tz-card:before,
    .pys-tz-info-card:before{
      content:"";
      position:absolute;
      inset:0;
      background:
        radial-gradient(circle at 12% 0%,rgba(0,229,196,.12),transparent 32%),
        radial-gradient(circle at 92% 100%,rgba(247,0,122,.10),transparent 34%);
      pointer-events:none;
    }

    .pys-tz-card > *,
    .pys-tz-info-card > *{
      position:relative;
      z-index:2;
    }

    .pys-tz-card:hover,
    .pys-tz-info-card:hover{
      transform:translateY(-5px);
      border-color:rgba(0,229,196,.25);
    }

    .pys-tz-icon{
      width:62px;
      height:62px;
      border-radius:20px;
      display:flex;
      align-items:center;
      justify-content:center;
      margin-bottom:22px;
      color:#111;
      background:linear-gradient(135deg,var(--pys-cyan),var(--pys-pink));
      box-shadow:0 18px 38px rgba(0,229,196,.17);
      position:relative;
      overflow:hidden;
    }

    .pys-tz-icon:after{
      content:"";
      position:absolute;
      inset:-35%;
      background:linear-gradient(90deg,transparent,rgba(255,255,255,.35),transparent);
      transform:rotate(35deg) translateX(-130%);
      animation:pysIconShine 4.8s ease-in-out infinite;
    }

    @keyframes pysIconShine{
      0%,65%{transform:rotate(35deg) translateX(-130%)}
      82%,100%{transform:rotate(35deg) translateX(130%)}
    }

    .pys-tz-icon svg{
      width:30px;
      height:30px;
      stroke:currentColor;
      fill:none;
      stroke-width:2;
      stroke-linecap:round;
      stroke-linejoin:round;
      position:relative;
      z-index:2;
    }

    .pys-tz-card h3,
    .pys-tz-info-card h3{
      margin:0 0 14px;
      color:#fff;
      font-size:1.3rem;
      letter-spacing:-.025em;
    }

    .pys-tz-card p,
    .pys-tz-info-card p{
      margin:0;
      color:#d4d8d6;
      line-height:1.82;
      font-size:.97rem;
    }

    .pys-tz-metric{
      min-height:178px;
      border-radius:26px;
      padding:26px;
      background:rgba(255,255,255,.055);
      border:1px solid rgba(255,255,255,.11);
      box-shadow:0 18px 44px rgba(0,0,0,.20);
      position:relative;
      overflow:hidden;
      transition:.28s ease;
    }

    .pys-tz-metric:hover{
      transform:translateY(-5px);
      background:rgba(255,255,255,.07);
    }

    .pys-tz-metric:after{
      content:"";
      position:absolute;
      width:120px;
      height:120px;
      right:-42px;
      bottom:-42px;
      border-radius:999px;
      background:radial-gradient(circle,rgba(0,229,196,.2),transparent 70%);
    }

    .pys-tz-metric strong{
      display:block;
      margin-bottom:12px;
      font-family:"Optima","Optima LT Std","Candara","Segoe UI",Arial,sans-serif;
      font-size:2.2rem;
      font-weight:400;
      letter-spacing:-.05em;
      color:#fff;
      position:relative;
      z-index:2;
    }

    .pys-tz-metric span{
      display:block;
      color:#cfd5d2;
      line-height:1.55;
      font-size:.92rem;
      position:relative;
      z-index:2;
    }

    .pys-tz-editorial{
      border-radius:38px;
      padding:70px;
      background:
        radial-gradient(circle at top left,rgba(0,229,196,.16),transparent 28%),
        radial-gradient(circle at bottom right,rgba(247,0,122,.15),transparent 28%),
        linear-gradient(135deg,#141516,#1b1117);
      border:1px solid rgba(255,255,255,.12);
      box-shadow:0 28px 70px rgba(0,0,0,.30);
      position:relative;
      overflow:hidden;
    }

    .pys-tz-editorial:after{
      content:"";
      position:absolute;
      inset:18px;
      border-radius:28px;
      border:1px solid rgba(255,255,255,.07);
      pointer-events:none;
    }

    .pys-tz-editorial h2{
      position:relative;
      z-index:2;
      margin:0;
      font-family:"Optima","Optima LT Std","Candara","Segoe UI",Arial,sans-serif;
      font-size:clamp(2.3rem,5vw,5rem);
      line-height:.96;
      font-weight:400;
      letter-spacing:-.055em;
      color:#fff;
    }

    .pys-tz-editorial p{
      position:relative;
      z-index:2;
      max-width:870px;
      margin:26px 0 0;
      color:#d4d9d7;
      line-height:1.9;
      font-size:1.02rem;
    }

    .pys-tz-path{
      display:grid;
      gap:18px;
    }

    .pys-tz-path-item{
      display:grid;
      grid-template-columns:76px 1fr;
      gap:22px;
      align-items:start;
      padding:26px;
      border-radius:28px;
      background:rgba(255,255,255,.055);
      border:1px solid rgba(255,255,255,.11);
      box-shadow:0 16px 40px rgba(0,0,0,.18);
      transition:.28s ease;
    }

    .pys-tz-path-item:hover{
      transform:translateX(6px);
      border-color:rgba(0,229,196,.22);
    }

    .pys-tz-path-num{
      width:58px;
      height:58px;
      border-radius:18px;
      display:flex;
      align-items:center;
      justify-content:center;
      background:linear-gradient(135deg,var(--pys-cyan),var(--pys-pink));
      color:#111;
      font-weight:950;
      letter-spacing:-.03em;
    }

    .pys-tz-path-item h3{
      margin:0 0 8px;
      color:#fff;
      font-size:1.2rem;
    }

    .pys-tz-path-item p{
      margin:0;
      color:#d4d9d7;
      line-height:1.78;
    }

    .pys-tz-properties{
      overflow:hidden;
      border-radius:34px;
      border:1px solid rgba(255,255,255,.12);
      background:
        radial-gradient(circle at top left,rgba(0,229,196,.11),transparent 32%),
        radial-gradient(circle at bottom right,rgba(247,0,122,.10),transparent 34%),
        linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,.035));
      box-shadow:0 22px 54px rgba(0,0,0,.24);
    }

    .pys-tz-properties-row{
      display:grid;
      grid-template-columns:.82fr 1.18fr;
      border-bottom:1px solid rgba(255,255,255,.1);
    }

    .pys-tz-properties-row:last-child{border-bottom:0}

    .pys-tz-properties-cell{
      padding:24px;
      color:#d4d9d7;
      line-height:1.65;
      border-right:1px solid rgba(255,255,255,.1);
      font-size:.96rem;
    }

    .pys-tz-properties-cell:last-child{border-right:0}

    .pys-tz-properties-head .pys-tz-properties-cell{
      color:#fff;
      font-weight:950;
      text-transform:uppercase;
      letter-spacing:.09em;
      font-size:.72rem;
      background:rgba(255,255,255,.045);
    }

    .pys-tz-properties-cell strong{
      color:#fff;
    }

    .pys-tz-product-wrap{
      display:grid;
      grid-template-columns:.95fr 1.05fr;
      gap:34px;
      align-items:center;
    }

    .pys-tz-product-card{
      display:grid;
      grid-template-columns:210px 1fr;
      gap:22px;
      align-items:center;
      overflow:hidden;
      border-radius:34px;
      background:#f7f7f5;
      color:#111;
      box-shadow:0 28px 70px rgba(0,0,0,.34);
      border:1px solid rgba(255,255,255,.12);
      transition:.28s ease;
      position:relative;
    }

    .pys-tz-product-card:hover{
      transform:translateY(-6px);
      box-shadow:0 34px 78px rgba(0,0,0,.42);
    }

    .pys-tz-product-image{
      min-height:300px;
      height:100%;
      display:flex;
      align-items:center;
      justify-content:center;
      padding:26px;
      background:
        radial-gradient(circle at top left,rgba(0,229,196,.28),transparent 38%),
        radial-gradient(circle at bottom right,rgba(247,0,122,.18),transparent 36%),
        linear-gradient(145deg,#fff,#ecece8);
    }

    .pys-tz-product-image img{
      width:100%;
      max-width:180px;
      max-height:245px;
      object-fit:contain;
      filter:drop-shadow(0 18px 24px rgba(0,0,0,.17));
      transition:.28s ease;
    }

    .pys-tz-product-card:hover img{
      transform:scale(1.04) rotate(-1deg);
    }

    .pys-tz-product-body{
      padding:30px 30px 30px 0;
    }

    .pys-tz-product-label{
      display:inline-flex;
      padding:8px 12px;
      border-radius:999px;
      background:rgba(17,17,17,.08);
      color:#171717;
      font-size:.62rem;
      font-weight:950;
      letter-spacing:.1em;
      text-transform:uppercase;
      margin-bottom:14px;
    }

    .pys-tz-product-body h3{
      margin:0 0 12px;
      color:#111;
      font-size:1.7rem;
      line-height:1.05;
      letter-spacing:-.045em;
    }

    .pys-tz-product-body p{
      margin:0 0 20px;
      color:#545454;
      line-height:1.65;
      font-size:.94rem;
    }

    .pys-tz-product-link{
      display:inline-flex;
      align-items:center;
      gap:9px;
      color:#111!important;
      font-size:.72rem;
      text-transform:uppercase;
      letter-spacing:.1em;
      font-weight:950;
    }

    .pys-tz-product-link:after{
      content:"→";
      color:var(--pys-pink);
      font-size:1rem;
    }

    .pys-tz-faq{
      display:grid;
      gap:14px;
    }

    .pys-tz-faq-item{
      border-radius:24px;
      overflow:hidden;
      background:rgba(255,255,255,.055);
      border:1px solid rgba(255,255,255,.12);
      box-shadow:0 16px 40px rgba(0,0,0,.18);
    }

    .pys-tz-faq-btn{
      width:100%;
      border:0;
      background:transparent;
      color:#fff;
      padding:22px 24px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:20px;
